// TypeScript Version: 4.1

/**
* Scale kind.
*/
type ScaleKind = 'all' | 'quantitative' | 'discrete' | 'discretizing';

/**
* Returns a list of supported scale names.
*
* @param kind - scale kind
* @returns list of scale names
*
* @example
* var out = scales();
* // e.g., returns [ 'linear', 'log', ... ]
*
* @example
* var list = scales( 'discrete' );
* // e.g., returns [ 'ordinal', 'band', ... ]
*/
declare function scales( kind?: ScaleKind ): Array<string>;


// EXPORTS //

export = scales;
